"""Record the exact standalone V20 artifact after sequential native checks."""
from pathlib import Path
import json,hashlib
root=Path(__file__).resolve().parents[2];base=root/'output/elyndor/pixellab-v20'
def read(name):return json.loads((base/name).read_text(encoding='utf-8'))
a=json.loads((root/'output/elyndor/continuous-standalone-audit.json').read_text());reg=read('regression.json');revision=read('records/report.json');repairs=read('revision/report.json');coached=read('coached/report.json');campaign=read('campaign/report.json');performance=read('performance/native.json');combat=read('combat-profile-final.json');atlas=read('atlas-performance.json');voices=read('audio-audit.json');sounds=read('soundtrack-audit.json');water=read('water/report.json');locations=read('locations/report.json');macro=read('overworld/report.json')
sha=hashlib.sha256((root/'index.html').read_bytes()).hexdigest()
assert sha==reg['sha256']==a['sha256'] and a['sourceMatchesArtifact'] and not a['cropWarnings']
assert len(reg['checks'])==28 and all(q['pass']for q in reg['checks'])
assert all(q['pass']for q in [repairs,revision,coached,atlas,voices,sounds,water,locations,macro])
assert campaign['campaign']['final']=='complete' and not campaign['errors'] and not campaign['voiceMissing']
assert not combat['newPrograms'] and combat['cpu']['p95']<25
pump=read('pump-fixed.json');assert not pump['errors'] and not pump['newPrograms'] and pump['tick']['p95']<10 and pump['tick']['max']<50
transcripts=json.loads((root/'elyndor/audio/transcription-audit-v18.json').read_text());assert transcripts['clips']==10 and not transcripts['unresolvedWordDifferences']
r={'release':'elyndor-2026-10-29-stair-traversal-coherent-river-v20','game':'The Last Light of Elyndor','artifact':{'file':'index.html','bytes':a['bytes'],'sha256':sha,'offline':True},
 'comparison':{'baselineCommit':'1a62326614e7727eabb1698d62ad6d4329a244b7','at':'2026-10-28T10:00:00-04:00','timezone':'America/New_York','deploymentRun':40644508527,'baselineRecordings':306,'currentRecordings':385,'label':'Most recent 10 AM before the overnight October 29 update'},
 'changes':['The extended stair flight is graded from the actual first tread rather than the nominal lower terrace, eliminating the 0.518 metre impassable join','Eleven extended lower treads limit the join and each rise to less than 0.25 metres; existing building collision is retained','Continuous textured ground backing closes the small sky gap beside the neighboring stairs','One coherent world-space water shader replaces stacked periodic ripple and shoreline bands; low river water has irregular moving surface detail','Legacy gate combat-smoke emission and old fixed foam points are removed; sluice spray uses an additive material without dark droplets','Cascade reflection sources are relinked to their actual upper and lower pools; water effects do not reflect into themselves and fill-time reflection planes match the sampled level','Opening the full-width gate retains the propagating river release, connected falls and downstream filling; foam and surface texture move downstream','The title changelog compares the current game with the GitHub build verified live at 10 AM Eastern on October 28, including materials, voices and sound, atlas, tutorials, combat, saves and runtime preparation'],
 'art':{'generator':'PixelLab','nativeSelectedFamilies':41,'runtimeFamilies':42,'packedSpritePoses':a['packedPoses'],'sourceCropWarnings':0,'newNativeMaterialPages':0,'materialSize':[512,512],'rejectedCandidatesExcluded':True},
 'audio':{'provider':'ElevenLabs','recordedVoices':voices['clips'],'soundAssets':sounds['sounds'],'newNarration':0,'newSoundEffects':0,'offline':True,'embeddedCredential':False,'transcription':transcripts},
 'validation':{'checks':reg['checks'],'revisionFeatures':revision,'stairAndRiverRepairs':repairs,'keyboardStairCrossings':len(repairs['walks']),'stairEdgeSamples':sum(q['count']for q in repairs['edges']),'coachedBattleRegression':coached,'stairFloorMaxGapMetres':max(q['gap']for q in revision['steps']),'locations':locations,'sourceMatchesArtifact':True,'storyProgressionSteps':len(campaign['campaign']['log']),'storyBattles':len(campaign['campaign']['battles']),'restoredLights':len(campaign['campaign']['restored']),'saveLoad':campaign['persistence'],'waterJoinMaxGapMetres':max(j['gap']for row in coached['water']for j in row['joins']),'overworldApproaches':macro},
 'performance':{'device':performance['device'],'nativeScenarios':performance['scenarios'],'pump':read('pump-fixed.json'),'tutorial':read('onboarding-performance.json'),'combatRenderCPU':combat['cpu'],'newCombatPrograms':len(combat['newPrograms']),'atlas':atlas,'scope':'Native Chrome on the recorded test GPU; performance varies by hardware.'}}
(root/'release.json').write_text(json.dumps(r,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');print(json.dumps({'release':r['release'],'bytes':a['bytes'],'sha256':sha,'checks':len(reg['checks']),'audioAssets':voices['clips']+sounds['sounds']}))
